import{_ as r,c as e,o as t,af as n}from"./chunks/framework.BKeRpnBD.js";const c=JSON.parse('{"title":"典籍导读","description":"典籍导读，整理自 App 的免费易经学习文档。","frontmatter":{"title":"典籍导读","description":"典籍导读，整理自 App 的免费易经学习文档。"},"headers":[],"relativePath":"zh/articles/references/index.md","filePath":"zh/articles/references/index.md"}'),l={name:"zh/articles/references/index.md"};function o(s,a,i,p,h,g){return t(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="高岛易断-高岛吞象-1832–1914" tabindex="-1">高岛易断（高岛吞象，1832–1914） <a class="header-anchor" href="#高岛易断-高岛吞象-1832–1914" aria-label="Permalink to “高岛易断（高岛吞象，1832–1914）”">​</a></h1><p><strong>《高岛易断》</strong>是日本明治期著名的易占著作。作者通称<strong>高岛吞象</strong>，本名<strong>高岛嘉右卫门</strong>，活跃于开港后的<strong>横滨</strong>，兼具实业家与易占家身分。</p><p>下面用一条更「可读的故事线」，把高岛吞象与《周易》的相遇、转折、以及他如何把占筮带回人间烟火讲清楚。</p><h2 id="一条故事线-从牢狱到《易》" tabindex="-1">一条故事线：从牢狱到《易》 <a class="header-anchor" href="#一条故事线-从牢狱到《易》" aria-label="Permalink to “一条故事线：从牢狱到《易》”">​</a></h2><p>据传，高岛吞象早年经商，既要承担家业与债务，也在剧烈变动的时代里摸索出路。因涉足当时敏感的货币兑换牟利（利用金银比价差），最终<strong>被捕入狱</strong>。</p><p>狱中环境恶劣、秩序混乱，生死往往只在一线。就在那样的地方，他偶然见到一本被遗落的<strong>《易经》</strong>。那不是「算命的小册子」，而是一套能把人心从恐惧里拉回秩序的语言：卦象教人看形势，卦辞教人辨方向，爻辞教人守进退。</p><p>他在狱中无事可做，便日夜研读，甚至以纸捻作筮草，替囚犯占卦。占卜在牢房里原是苦中作乐，却因屡屡应验而渐成信心——从此，《易》不再只是书页上的古文，而变成能照见现实的镜子。</p><h2 id="越狱与一卦-履之井" tabindex="-1">越狱与一卦：履之井 <a class="header-anchor" href="#越狱与一卦-履之井" aria-label="Permalink to “越狱与一卦：履之井”">​</a></h2><p>传记里最戏剧的一段，是<strong>越狱</strong>。同囚策画逃亡，他以风险过大而拒绝，并占得「<strong>履之井</strong>」：履，如踏虎尾，凶险逼人却未必立刻受害；井，绳索升降，于困局中仍有一线生机。</p><p>后来越狱仍然爆发，兵刃围堵、囚犯躁动，局势迅速失控。据说他在混乱中负伤，却于千钧一发之际，沿着牢内晾衣的绳索攀上，在衣物之间藏身，竟得以逃过屠戮——那一刻，他才真正读懂「井」：不是井水，而是<strong>绳</strong>；不是奔逃，而是<strong>借势而升</strong>。</p><p>不论细节如何流传，这段故事留下一个核心：高岛把卦当成「吉凶标签」，也把卦当成「行动提示」。危险不是被消除，而是被看见、被安排、被穿过。</p><h2 id="出狱之后-以卦助人-也以卦成事" tabindex="-1">出狱之后：以卦助人，也以卦成事 <a class="header-anchor" href="#出狱之后-以卦助人-也以卦成事" aria-label="Permalink to “出狱之后：以卦助人，也以卦成事”">​</a></h2><p>据说他后来因为占卜屡验，甚至被狱方请教，最终得以<strong>减刑出狱</strong>。出狱后他转往横滨，在新旧交错的城市里重建人生：</p><ul><li>作为<strong>实业家</strong>：经营木材事业，参与旅馆等近代设施，亦涉足城市建设与交通（如铁路）等议题。</li><li>作为<strong>易占家</strong>：面向平民、商人乃至时局要事，以卦象爻义提供决策参考；并以大量占例把方法整理成书，成为后人研读的材料。</li></ul><p>另一段广为人知的传说是：他曾以占象力劝某位要人避免远行，但最终仍未能阻止悲剧发生。这让人看到《易》的另一面：占筮不保证改写命运，却常常提供「<strong>提前知道代价</strong>」的机会。</p><h2 id="高岛与《周易》-他延续了什么" tabindex="-1">高岛与《周易》：他延续了什么 <a class="header-anchor" href="#高岛与《周易》-他延续了什么" aria-label="Permalink to “高岛与《周易》：他延续了什么”">​</a></h2><p>《周易》在中国古代形成——相传伏羲画八卦，文王、周公推演成卦爻辞，孔子及后儒整理「十翼」而成经典体系。易学不仅是哲学，也成为占筮的方法。</p><p>高岛吞象的贡献，不在于「另造一部易」，而在于把《周易》重新带回一种可操作的秩序：<strong>以卦辞爻辞为核心，落到具体人事与决策</strong>，并以占例反复验证、修正、传授。也因此，《高岛易断》更像一本「可对照的占例教材」。</p><blockquote><p>提醒：传记与占例往往带有叙事夸张与时代立场（含战事与政治背景）。阅读时宜保持史观与批判性，取其方法之长。</p></blockquote><h2 id="本-app-收录内容-依卦呈现" tabindex="-1">本 App 收录内容（依卦呈现） <a class="header-anchor" href="#本-app-收录内容-依卦呈现" aria-label="Permalink to “本 App 收录内容（依卦呈现）”">​</a></h2><ul><li><strong>卦名解读</strong>：先交代卦名与卦象结构，建立阅读入口</li><li><strong>卦辞 / 象辞</strong>：提供原典对应的要点文本</li><li><strong>占断（高岛易断）</strong>：每卦的精炼占解条目</li><li><strong>爻变详解</strong>：逐爻的变化解读与占例整理</li></ul><p>本页所示内容与图片仅供学习与参考；原书文本为公版资料。</p><hr><h1 id="焦氏易林" tabindex="-1">焦氏易林 <a class="header-anchor" href="#焦氏易林" aria-label="Permalink to “焦氏易林”">​</a></h1><p>《焦氏易林》又称《易林》，传为西汉易学家 <strong>焦延寿（字赣）</strong> 所作的诗体占书（作者归属亦有不同说法）。 它以《周易》六十四卦为基础，将「本卦 → 之卦」的组合系统化：<strong>每一卦各衍生六十四卦</strong>，合成 <strong>64×64＝4096</strong> 条占辞， 多用<strong>四言韵语</strong>呈现，把抽象卦象转写成更具画面感的意象与情境。</p><h2 id="与《周易》的故事线" tabindex="-1">与《周易》的故事线 <a class="header-anchor" href="#与《周易》的故事线" aria-label="Permalink to “与《周易》的故事线”">​</a></h2><p>《周易》重在卦象与卦爻辞的义理结构；而《易林》则像是一套「把卦意变成可读的诗句」的占筮语料库：</p><ul><li>以诗句补足卦象的情境（人事、物象、吉凶、得失）</li><li>让占断更容易抓住「象」与「机」</li><li>也成为后世象数易学与占筮实作的重要材料之一</li></ul><h2 id="本-app-如何使用《易林》" tabindex="-1">本 App 如何使用《易林》 <a class="header-anchor" href="#本-app-如何使用《易林》" aria-label="Permalink to “本 App 如何使用《易林》”">​</a></h2><p>本 App 会依你占得的「本卦 → 之卦」自动显示对应诗句，用来辅助解读：</p><ol><li>先抓诗中的关键意象（人物、动作、地点、器物、吉凶词）</li><li>再对照你的问题脉络与当下处境</li><li>最后回到《周易》卦象与动爻，做整体判断</li></ol><h2 id="翻译说明" tabindex="-1">翻译说明 <a class="header-anchor" href="#翻译说明" aria-label="Permalink to “翻译说明”">​</a></h2><p>英文诗句为中文整理翻译而来，偏直译；中文仍应作为主要依据，英文仅供参考。</p><ul><li>读法：先观诗中关键意象，再结合当事问题、卦象与动爻综合判读。</li><li>来源说明：英文翻译从中文本《焦氏易林》整理翻译而来，诗句以直译为主，难以完全传达中文之准确含义；以中文为准，英文仅供参考。</li></ul>',34)])])}const b=r(l,[["render",o]]);export{c as __pageData,b as default};
